-- Generated by scripts/current-sql.mjs; documentation only.
-- Signature: app.expand_repeat_items(p_component jsonb, p_values jsonb)
-- Owner: cms_migration_owner
-- ACL: {cms_migration_owner=X/cms_migration_owner}

CREATE OR REPLACE FUNCTION app.expand_repeat_items(p_component jsonb, p_values jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE node jsonb; part jsonb; nodes jsonb := '[]'::jsonb; body jsonb := '[]'::jsonb; open_id text;
        has_slots boolean := p_component ? 'slots'; spec jsonb; fields jsonb; min_items int; max_items int;
        item_keys text[]; item_key text;
BEGIN
  IF p_component->>'definition_kind' = 'structured' OR NOT EXISTS (
    SELECT 1 FROM jsonb_array_elements(COALESCE(p_component#>'{compiled_ast,nodes}', '[]'::jsonb)) entry
     WHERE jsonb_typeof(entry.value) = 'object' AND entry.value ? 'marker'
  ) THEN
    RETURN p_component;
  END IF;

  FOR node IN SELECT entry.value FROM jsonb_array_elements(p_component#>'{compiled_ast,nodes}') entry LOOP
    IF open_id IS NULL THEN
      IF node->>'kind' = 'slot' AND node->>'slotKind' = 'repeat' AND node->>'marker' = 'start' THEN
        open_id := node->>'slotId'; body := '[]'::jsonb;
      ELSIF node ? 'marker' THEN
        RETURN jsonb_set(p_component, '{compiled_ast,nodes}', '[]'::jsonb);
      ELSE
        nodes := nodes || jsonb_build_array(node);
      END IF;
      CONTINUE;
    END IF;

    IF NOT node ? 'marker' THEN body := body || jsonb_build_array(node); CONTINUE; END IF;
    IF node->>'marker' IS DISTINCT FROM 'end' OR node->>'slotId' IS DISTINCT FROM open_id THEN
      RETURN jsonb_set(p_component, '{compiled_ast,nodes}', '[]'::jsonb);
    END IF;

    -- The item's declared fields and limit, when the component carries its
    -- slots (pages and recipes do). A list the definition does not declare
    -- renders nothing.
    spec := NULL; fields := NULL;
    IF has_slots THEN
      SELECT s.value->'constraints'->'item' INTO spec
        FROM jsonb_array_elements(CASE WHEN jsonb_typeof(p_component->'slots') = 'array' THEN p_component->'slots' ELSE '[]'::jsonb END) s
       WHERE s.value->>'id' = open_id AND s.value->>'kind' = 'repeat' LIMIT 1;
      IF jsonb_typeof(spec->'fields') = 'array' THEN
        SELECT COALESCE(jsonb_agg(f.value->>'id'), '[]'::jsonb) INTO fields FROM jsonb_array_elements(spec->'fields') f;
      END IF;
    END IF;
    min_items := LEAST(48, GREATEST(0, CASE WHEN jsonb_typeof(spec->'min') = 'number' AND (spec->>'min') ~ '^[0-9]+$' THEN (spec->>'min')::int ELSE 0 END));
    max_items := GREATEST(GREATEST(min_items, 1), LEAST(48,
      CASE WHEN jsonb_typeof(spec->'max') = 'number' AND (spec->>'max') ~ '^[0-9]+$' THEN (spec->>'max')::int ELSE 48 END));

    item_keys := '{}';
    IF NOT has_slots OR fields IS NOT NULL THEN
      SELECT COALESCE(array_agg(k.key ORDER BY k.ord), '{}') INTO item_keys FROM (
        SELECT first.key, first.ord FROM (
          SELECT DISTINCT ON (e.value #>> '{}') e.value #>> '{}' AS key, e.ord
            FROM jsonb_array_elements(CASE WHEN jsonb_typeof(p_values->open_id->'items') = 'array'
                   THEN p_values->open_id->'items' ELSE '[]'::jsonb END) WITH ORDINALITY AS e(value, ord)
           WHERE jsonb_typeof(e.value) = 'string' AND (e.value #>> '{}') ~ '^[a-z][a-z0-9]{0,7}$'
           ORDER BY e.value #>> '{}', e.ord
        ) first ORDER BY first.ord LIMIT max_items
      ) k;
    END IF;

    FOREACH item_key IN ARRAY item_keys LOOP
      FOR part IN SELECT entry.value FROM jsonb_array_elements(body) entry LOOP
        IF part->>'kind' = 'slot' THEN
          IF fields IS NOT NULL AND NOT fields ? (part->>'slotId') THEN CONTINUE; END IF;
          part := jsonb_set(part, '{slotId}', to_jsonb(open_id || '__' || item_key || '__' || (part->>'slotId')));
        END IF;
        nodes := nodes || jsonb_build_array(part);
      END LOOP;
    END LOOP;
    open_id := NULL;
  END LOOP;

  IF open_id IS NOT NULL THEN RETURN jsonb_set(p_component, '{compiled_ast,nodes}', '[]'::jsonb); END IF;
  RETURN jsonb_set(p_component, '{compiled_ast,nodes}', nodes);
END
$function$
